using System;using System.IO;using System.Linq;using System.Collections.Generic;using UnityEngine;using UnityEditor;
namespace Deepsea.Editor {public static class CoastTreeTools {
 static int Root(int[] p,int a){while(p[a]!=a){p[a]=p[p[a]];a=p[a];}return a;}static void Join(int[] p,int a,int b){a=Root(p,a);b=Root(p,b);if(a!=b)p[b]=a;}
 static List<int[]> Groups(Mesh m,int sub){int[] t=m.GetTriangles(sub);var p=Enumerable.Range(0,m.vertexCount).ToArray();for(int i=0;i<t.Length;i+=3){Join(p,t[i],t[i+1]);Join(p,t[i],t[i+2]);}var g=new Dictionary<int,List<int>>();for(int i=0;i<t.Length;i+=3){int k=Root(p,t[i]);if(!g.TryGetValue(k,out var list))g[k]=list=new List<int>();list.Add(t[i]);list.Add(t[i+1]);list.Add(t[i+2]);}return g.Values.Select(x=>x.ToArray()).ToList();}
 public static void Analyze(){var m=AssetDatabase.LoadAssetAtPath<GameObject>("Assets/Deepsea/ThirdParty/CoastSlice/island_tree_01/island_tree_01.fbx").GetComponentInChildren<MeshFilter>().sharedMesh;var text=new List<string>{"SOURCE verts="+m.vertexCount+" submeshes="+m.subMeshCount};for(int s=0;s<m.subMeshCount;s++){var groups=Groups(m,s);text.Add("sub="+s+" triangles="+m.GetTriangles(s).Length/3+" components="+groups.Count+" histogram="+string.Join(",",groups.GroupBy(x=>x.Length/3).OrderByDescending(x=>x.Count()).Take(25).Select(x=>x.Key+"tris:"+x.Count())));var v=m.vertices;foreach(var a in groups.OrderByDescending(x=>x.Length).Take(3)){var b=new Bounds(v[a[0]],Vector3.zero);foreach(int i in a)b.Encapsulate(v[i]);text.Add("largest tris="+a.Length/3+" bounds="+b);}}Directory.CreateDirectory("Verification/coast-perf");File.WriteAllLines("Verification/coast-perf/tree-analysis.txt",text);Debug.Log(string.Join("\n",text));}

 static Vector3 SafeNormal(Vector3 v){double length=Math.Sqrt((double)v.x*v.x+(double)v.y*v.y+(double)v.z*v.z);return length>1e-24?v/(float)length:Vector3.up;}
 public static Mesh Cards(Mesh source,int level){
  string path="Assets/Deepsea/Resources/CoastSlice/TreeCardsV2-"+level+".asset";var cached=AssetDatabase.LoadAssetAtPath<Mesh>(path);if(cached!=null)return cached;
  var sv=source.vertices;var sn=source.normals;var su=source.uv;var st=source.tangents;var v=new List<Vector3>();var n=new List<Vector3>();var uv=new List<Vector2>();var tan=new List<Vector4>();var sub=new List<int[]>();int converted=0,fallback=0;double worst=0;
  for(int s=0;s<source.subMeshCount;s++){var triangles=new List<int>();var groups=Groups(source,s);var random=new System.Random(771+s);
   foreach(var group in groups){var unique=group.Distinct().ToArray();
    if(s==0){var map=new Dictionary<int,int>();foreach(int old in unique){map[old]=v.Count;v.Add(sv[old]);n.Add(sn[old]);uv.Add(su[old]);tan.Add(st.Length==sv.Length?st[old]:new Vector4(1,0,0,1));}foreach(int old in group)triangles.Add(map[old]);continue;}
    double chance=random.NextDouble();if(level==1&&chance>.55||level==2&&chance>.28)continue;
    Vector3 center=Vector3.zero,normal=Vector3.zero;Vector2 mean=Vector2.zero,min=new Vector2(float.MaxValue,float.MaxValue),max=new Vector2(float.MinValue,float.MinValue);
    foreach(int i in unique){center+=sv[i];normal+=sn[i];mean+=su[i];min=Vector2.Min(min,su[i]);max=Vector2.Max(max,su[i]);}center/=unique.Length;mean/=unique.Length;
    double uu=0,vv=0,uvv=0;Vector3 pu=Vector3.zero,pv=Vector3.zero;
    foreach(int i in unique){var q=su[i]-mean;var p=sv[i]-center;uu+=q.x*q.x;vv+=q.y*q.y;uvv+=q.x*q.y;pu+=p*q.x;pv+=p*q.y;}
    double det=uu*vv-uvv*uvv;
    if(Math.Abs(det)<1e-16){fallback++;var map=new Dictionary<int,int>();foreach(int old in unique){map[old]=v.Count;v.Add(sv[old]);n.Add(sn[old]);uv.Add(su[old]);tan.Add(st.Length==sv.Length?st[old]:new Vector4(1,0,0,1));}foreach(int old in group)triangles.Add(map[old]);continue;}
    var a=(pu*(float)vv-pv*(float)uvv)/(float)det;var b=(pv*(float)uu-pu*(float)uvv)/(float)det;var norm=SafeNormal(Vector3.Cross(SafeNormal(a),SafeNormal(b)));if(Vector3.Dot(norm,normal)<0)norm=-norm;var tangent=SafeNormal(a);float hand=Vector3.Dot(Vector3.Cross(norm,tangent),b)>=0?1:-1;
    float enlarge=level==0?1:level==1?1.15f:1.32f;Vector2[] corners={new Vector2(min.x,min.y),new Vector2(max.x,min.y),new Vector2(min.x,max.y),new Vector2(max.x,max.y)};int start=v.Count;
    foreach(var corner in corners){var q=corner-mean;v.Add(center+(a*q.x+b*q.y)*enlarge);n.Add(norm);uv.Add(corner);tan.Add(new Vector4(tangent.x,tangent.y,tangent.z,hand));}
    bool forward=Vector3.Dot(Vector3.Cross(a,b),norm)>0;int[] quad=forward?new[]{0,1,2,2,1,3}:new[]{0,2,1,2,3,1};foreach(int i in quad)triangles.Add(start+i);converted++;
    foreach(int i in unique){var q=su[i]-mean;worst=Math.Max(worst,Vector3.Distance(sv[i],center+a*q.x+b*q.y));}
   }sub.Add(triangles.ToArray());
  }
  var mesh=new Mesh{name="岛树叶片卡片 LOD"+level,indexFormat=UnityEngine.Rendering.IndexFormat.UInt32};mesh.SetVertices(v);mesh.SetNormals(n);mesh.SetUVs(0,uv);mesh.SetTangents(tan);mesh.subMeshCount=sub.Count;for(int i=0;i<sub.Count;i++)mesh.SetTriangles(sub[i],i);mesh.RecalculateBounds();if(mesh.normals.Any(q=>float.IsNaN(q.x)||float.IsInfinity(q.x)||q.sqrMagnitude<.9f))throw new Exception("Invalid tree card normals");AssetDatabase.CreateAsset(mesh,path);Debug.Log("TREE_CARDS level="+level+" vertices="+v.Count+" triangles="+sub.Sum(x=>x.Length)/3+" cards="+converted+" fallback="+fallback+" maxFlatError="+worst);return mesh;
 }
 public static void Install(GameObject instance){var f=instance.GetComponentInChildren<MeshFilter>();var r=f.GetComponent<MeshRenderer>();var original=AssetDatabase.LoadAssetAtPath<GameObject>("Assets/Deepsea/ThirdParty/CoastSlice/island_tree_01/island_tree_01.fbx").GetComponentInChildren<MeshFilter>().sharedMesh;f.sharedMesh=Cards(original,0);var lods=new List<LOD>{new LOD(.12f,new Renderer[]{r})};for(int i=1;i<=2;i++){var obj=new GameObject("岛树细节层级 "+i);obj.transform.SetParent(f.transform==instance.transform?instance.transform:f.transform.parent,false);obj.transform.localPosition=f.transform==instance.transform?Vector3.zero:f.transform.localPosition;obj.transform.localRotation=f.transform==instance.transform?Quaternion.identity:f.transform.localRotation;obj.transform.localScale=f.transform==instance.transform?Vector3.one:f.transform.localScale;obj.AddComponent<MeshFilter>().sharedMesh=Cards(original,i);var rr=obj.AddComponent<MeshRenderer>();rr.sharedMaterials=r.sharedMaterials;lods.Add(new LOD(i==1?.05f:.012f,new Renderer[]{rr}));}var group=instance.GetComponent<LODGroup>();if(group==null)group=instance.AddComponent<LODGroup>();group.SetLODs(lods.ToArray());group.RecalculateBounds();}
public static void RepairPrefab(){string path="Assets/Deepsea/Resources/CoastSlice/island_tree_01.prefab";var instance=PrefabUtility.LoadPrefabContents(path);try{foreach(var t in instance.GetComponentsInChildren<Transform>().Where(t=>t!=instance.transform&&t.name.StartsWith("岛树细节层级")).ToArray())UnityEngine.Object.DestroyImmediate(t.gameObject);Install(instance);if(instance.GetComponentsInChildren<MeshFilter>().Length!=3)throw new Exception("Tree LOD children missing");PrefabUtility.SaveAsPrefabAsset(instance,path);}finally{PrefabUtility.UnloadPrefabContents(instance);}AssetDatabase.SaveAssets();CoastPerfBuild.Build();}
}}
